# Popover Details Configuration
# This file contains the lookup table and helper function for rendering 
# "Details" buttons with custom popovers next to download buttons.
#
# Structure:
#   - `details_lookup`: tibble mapping section_id to title and description text
#   - `create_details_button()`: helper function to render Details button with popover

# ============================================================================
# Details Lookup Table
# ============================================================================
# Instructions for adding entries:
# - section_id: matches the output$* ID from main_page_server.R
# - details_title: short, clear title for the popover
# - details_text: 1-3 sentence description of what the visualization shows
#

details_lookup <- tribble(
  ~section_id,              ~details_title,                        ~details_text,
  # ========== Demographics Section ==========
  "sex1",                  "Sex Details",                     "This plot shows the percent of people with HIV served at your clinic, by sex regardless of LAI ART use.",
  "race1",                 "Race Details",                    "This plot shows the percent of people with HIV served at your clinic, by race regardless of LAI ART use.",
  "ethnicity1",            "Ethnicity Details",               "This plot shows the percent of people with HIV served at your clinic, by ethnicity regardless of LAI ART use.",
  "age1",                  "Age Details",                     "This plot shows the percent of people with HIV served at your clinic, by age regardless of LAI ART use.",
  "insurance1",            "HIV Medication Payor Details",    "This plot shows the percent of people with HIV served at your clinic, by HIV medication payor regardless of LAI ART use. \n\nThe HIV medicator payor variable is created by combining two variables: health_care_coverage (the primary source of health care coverage the client had for any part of the reporting period; includes private insurance, Medicare, Medicaid, Veterans Health Administration, Indian Health Service, other health plans, or no insurance/uninsured) and secondary_payor (the payor of HIV medications if different or supplemental from health care coverage; includes ADAP and patient assistance programs). ",
  "keypop1",               "Key Population Details",          "This plot shows the percent of people with HIV served at your clinic, by key population regardless of LAI ART use. Key populations include patients with different housing or employment status, poverty level, primary language, incarceration history, or other social determinants of health measured by the clinic. ",
